*{box-sizing:border-box} :root{font-family:Manrope,system-ui,sans-serif;color:#f5f8fc;font-synthesis:none}html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101b28}button{font:inherit;color:inherit;cursor:pointer;border:0}#game-shell{height:100%;width:100%;padding:0}#viewport{height:100%;width:100%;position:relative;overflow:hidden;background:#9fcbd1}#viewport canvas#world{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(8,20,32,.35),transparent 24%,transparent 63%,rgba(5,14,24,.35));z-index:1}.glass{background:rgba(13,25,38,.78);border:1px solid rgba(255,255,255,.13);box-shadow:0 12px 35px rgba(8,16,24,.18);backdrop-filter:blur(16px);-webkit-backdrop-filter:blur(16px)}.topbar{position:absolute;z-index:3;top:24px;left:28px;right:28px;display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:12px}.brand-icon{height:38px;width:38px;border-radius:12px;background:#d9f36a;color:#14212a;font-weight:900;font-size:20px;display:grid;place-items:center;box-shadow:0 4px 14px #cbed5840}.brand strong{font-size:13px;letter-spacing:.16em;display:block}.brand small{font-size:9px;letter-spacing:.15em;color:#d0dbe0;display:block;margin-top:3px}.route-chip{display:flex;align-items:center;gap:12px;padding:11px 16px;border:1px solid #ffffff24;background:#112235b8;border-radius:30px;font:500 10px 'DM Mono',monospace;letter-spacing:.1em;color:#edf4f6}.route-chip i,.weather-pill i{height:15px;width:1px;background:#ffffff42}.route-chip>span:last-child{color:#d9f36a}.live-dot{height:7px;width:7px;border-radius:50%;background:#dbf66b;box-shadow:0 0 12px #dbf66b}.icon-button{background:#102235b8;border:1px solid #ffffff30;border-radius:24px;padding:11px 15px;font-size:12px;letter-spacing:.08em}.icon-button span{font-size:9px;margin-left:5px}.left-panel{position:absolute;z-index:3;top:104px;left:28px;width:254px;border-radius:15px;padding:18px 20px}.panel-kicker{font:500 9px 'DM Mono',monospace;letter-spacing:.16em;color:#aab8c5}.panel-kicker span{float:right;color:#d9f36a}.stop-name{font-size:22px;font-weight:800;letter-spacing:.02em;margin-top:8px}.stop-distance{display:flex;align-items:baseline;gap:4px;margin-top:10px;font:500 13px 'DM Mono',monospace}.stop-distance b{font-size:21px;color:#d9f36a}.stop-distance>span:nth-child(2){color:#9baab5;font-size:10px}.distance-track{height:3px;flex:1;background:#ffffff20;margin-left:10px;border-radius:9px;align-self:center;overflow:hidden}.distance-track i{height:100%;width:100%;display:block;background:#d9f36a;border-radius:9px}.stop-line{font-size:10px;color:#c0cbd2;margin-top:15px;display:flex;gap:8px;align-items:center}.line-dot{height:7px;width:7px;border-radius:50%;background:#77dbe1;box-shadow:0 0 9px #77dbe1}.divider{height:1px;background:#ffffff20;margin:16px 0 13px}.passenger-row{display:flex;justify-content:space-between;align-items:center;color:#aab8c5;font:500 9px 'DM Mono',monospace;letter-spacing:.1em}.passenger-row strong{font-size:14px;color:#f3f6f7}.passenger-row small{color:#80909d;font:inherit}.passenger-bar{height:4px;background:#ffffff20;border-radius:8px;margin-top:9px;overflow:hidden}.passenger-bar i{display:block;width:0;height:100%;background:#d9f36a;transition:width .5s}.right-panel{position:absolute;z-index:3;right:28px;top:104px;display:flex;align-items:flex-end;flex-direction:column;gap:12px}.weather-pill{height:37px;border-radius:20px;padding:0 13px;display:flex;align-items:center;gap:10px;font:500 9px 'DM Mono',monospace;letter-spacing:.08em}.weather-pill i{height:13px}.sun{color:#f1dd83;font-size:17px}.mini-map{width:168px;height:190px;border-radius:14px;padding:8px;position:relative;overflow:hidden}.mini-map canvas{width:100%;height:calc(100% - 17px);display:block}.map-label{font:500 8px 'DM Mono',monospace;color:#a9bac5;letter-spacing:.14em;text-align:center;padding-top:1px}.objective{position:absolute;z-index:4;bottom:132px;left:50%;transform:translateX(-50%);min-width:420px;padding:13px 15px;display:flex;align-items:center;gap:12px;background:rgba(14,29,43,.9);border:1px solid #ffffff23;border-radius:13px;box-shadow:0 12px 35px #06111b4a;backdrop-filter:blur(15px);transition:opacity .25s,transform .25s}.objective.hidden{opacity:0;pointer-events:none;transform:translate(-50%,10px)}.objective-icon{height:30px;width:30px;border-radius:9px;background:#d9f36a;color:#17252b;display:grid;place-items:center;font-size:17px}.objective>span:nth-child(2){flex:1}.objective strong{display:block;font:500 9px 'DM Mono',monospace;letter-spacing:.13em}.objective small{display:block;color:#aab8c5;font-size:10px;margin-top:4px}.objective button,.end-card button{background:#d9f36a;color:#14212a;border-radius:7px;padding:11px 14px;font-weight:800;font-size:10px;letter-spacing:.08em;white-space:nowrap}.objective button b,.end-card button b{font-size:15px;margin-left:9px}.bottom-ui{position:absolute;z-index:3;bottom:22px;left:28px;right:28px;display:flex;align-items:flex-end;justify-content:space-between}.speed-card{width:204px;border-radius:13px;padding:13px 16px 11px}.speed-top,.speed-footer{display:flex;justify-content:space-between;align-items:center;font:500 8px 'DM Mono',monospace;letter-spacing:.13em;color:#aab8c5}.speed-top span:last-child{border:1px solid #d9f36a77;border-radius:4px;color:#d9f36a;padding:3px 6px}.speed-readout{display:flex;align-items:baseline;gap:7px;margin:2px 0}.speed-readout b{font:500 42px 'DM Mono',monospace;letter-spacing:-.08em}.speed-readout span{font:500 9px 'DM Mono',monospace;color:#9eacb8}.speed-meter{height:3px;background:#ffffff20;border-radius:3px;overflow:hidden}.speed-meter i{display:block;height:100%;width:0;background:#d9f36a;transition:width .2s}.speed-footer{margin-top:9px;font-size:8px}.speed-footer b{color:#f5f8fc}.speed-footer span:last-child{color:#d9f36a}.drive-hint{position:absolute;left:50%;transform:translateX(-50%);bottom:20px;display:flex;align-items:center;gap:8px;padding:9px 13px;border-radius:8px;background:#0e1b2b9c;color:#c4cfd4;font:500 8px 'DM Mono',monospace;letter-spacing:.06em}.drive-hint span:nth-of-type(odd){border:1px solid #ffffff55;border-radius:4px;padding:4px 6px;color:white;font-size:9px}.drive-hint i{color:#d9f36a;font-style:normal}.controls-card{width:204px;border-radius:13px;padding:9px 13px}.control-row{height:34px;display:flex;justify-content:space-between;align-items:center}.control-row+.control-row{border-top:1px solid #ffffff1c}.control-label{font:500 8px 'DM Mono',monospace;letter-spacing:.08em;color:#9baab5}.control-button{display:flex;align-items:center;gap:6px;background:transparent;font:500 8px 'DM Mono',monospace;color:#d5dfe2}.control-button kbd{font:500 8px 'DM Mono',monospace;color:#9baab5;border:1px solid #ffffff38;border-radius:3px;padding:3px 4px;margin-left:2px}.door-icon,.brake-icon{color:#d9f36a;font-size:14px}.control-button.active{color:#d9f36a}.toast{position:absolute;z-index:5;top:94px;left:50%;transform:translate(-50%,-12px);opacity:0;pointer-events:none;background:#132638eb;border:1px solid #ffffff30;border-radius:20px;padding:10px 16px;font-size:11px;transition:.3s;box-shadow:0 8px 26px #0003}.toast.show{opacity:1;transform:translate(-50%,0)}#loading{position:absolute;inset:0;z-index:20;background:#9fcbd1;display:grid;place-content:center;justify-items:center;gap:12px;color:#263c49;font:500 10px 'DM Mono',monospace;letter-spacing:.2em;transition:opacity .6s}.loader-mark{height:50px;width:50px;border-radius:15px;background:#d9f36a;display:grid;place-items:center;color:#14212a;font:800 28px Manrope;letter-spacing:0;animation:bob 1s infinite alternate}@keyframes bob{to{transform:translateY(-5px)}}#loading.gone{opacity:0;pointer-events:none}.mobile-controls{display:none}.end-screen{position:absolute;z-index:8;inset:0;display:none;place-items:center;background:#09172488;backdrop-filter:blur(5px)}.end-screen.show{display:grid}.end-card{width:min(420px,calc(100vw - 32px));border-radius:20px;padding:32px;text-align:center;background:rgba(14,29,43,.94)}.end-emblem{width:42px;height:42px;border-radius:50%;background:#d9f36a;color:#192830;display:grid;place-items:center;font-size:22px;margin:0 auto 18px}.end-card .panel-kicker{color:#d9f36a}.end-card h1{font-size:32px;margin:8px 0}.end-card p{color:#afbdc7;font-size:12px;line-height:1.6;margin:0 auto 20px;max-width:290px}.score-grid{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid #ffffff21;border-bottom:1px solid #ffffff21;padding:16px 0;margin-bottom:20px}.score-grid b{display:block;font:500 20px 'DM Mono',monospace}.score-grid span{display:block;color:#aab8c5;font:500 7px 'DM Mono',monospace;letter-spacing:.08em;margin-top:5px}.end-card button{width:100%;padding:14px}.hidden{display:none!important}
@media(max-width:760px){.topbar{top:12px;left:12px;right:12px}.brand-icon{height:32px;width:32px;border-radius:10px}.brand{gap:8px}.brand strong{font-size:10px}.brand small{font-size:7px}.route-chip{gap:7px;padding:9px 10px;font-size:8px}.icon-button{padding:9px 10px}.icon-button span{display:none}.left-panel{top:70px;left:12px;width:190px;padding:12px 14px}.panel-kicker{font-size:7px}.stop-name{font-size:17px;margin-top:5px}.stop-distance{margin-top:4px}.stop-line{font-size:8px;margin-top:9px}.divider{margin:10px 0}.right-panel{right:12px;top:70px;gap:7px}.weather-pill{height:30px;padding:0 9px;font-size:7px;gap:6px}.mini-map{width:115px;height:130px;padding:5px}.map-label{font-size:6px}.bottom-ui{left:10px;right:10px;bottom:10px;align-items:flex-end}.speed-card{width:145px;padding:9px 10px}.speed-top,.speed-footer{font-size:7px}.speed-readout b{font-size:34px}.controls-card{width:150px;padding:6px 9px}.control-label{font-size:6px}.control-row{height:29px}.control-button{gap:4px;font-size:7px}.control-button kbd{display:none}.drive-hint{display:none}.objective{bottom:111px;min-width:0;width:calc(100% - 24px);gap:8px;padding:10px}.objective-icon{height:27px;width:27px}.objective strong{font-size:8px}.objective small{font-size:8px}.objective button{padding:10px 9px;font-size:8px}.mobile-controls{position:absolute;z-index:4;inset:auto 10px 90px;display:flex;justify-content:space-between;pointer-events:none}.mobile-controls button{pointer-events:auto;background:#12273bc9;border:1px solid #ffffff38;border-radius:50%;height:52px;width:52px;font-weight:800;touch-action:none;box-shadow:0 4px 14px #0003}.steer-controls,.pedal-controls{display:flex;gap:8px}.pedal-controls button{border-radius:16px;height:48px;width:64px;font-size:10px}.pedal-controls button:last-child{background:#d9f36a;color:#17252b}.mobile-controls button.pressed{transform:scale(.94);filter:brightness(1.3)}.toast{top:65px;font-size:9px;white-space:nowrap}}
@media(max-width:390px){.left-panel{width:165px}.mini-map{width:98px;height:112px}.route-chip{font-size:7px}.brand small{display:none}.controls-card{width:132px}.control-label{font-size:5px}.objective small{max-width:145px}}

import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const viewport = document.querySelector('#viewport');
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x9fcbd1);
scene.fog = new THREE.Fog(0x9fcbd1, 120, 470);
const camera = new THREE.PerspectiveCamera(58, innerWidth / innerHeight, .1, 700);
const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
renderer.setSize(innerWidth, innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.15;
renderer.domElement.id = 'world';
viewport.prepend(renderer.domElement);

scene.add(new THREE.HemisphereLight(0xe4f6ff, 0x788375, 2.15));
const sun = new THREE.DirectionalLight(0xffedcf, 3.0);
sun.position.set(-45, 70, -5); sun.castShadow = true;
sun.shadow.mapSize.set(1024, 1024); sun.shadow.camera.left = -65; sun.shadow.camera.right = 65; sun.shadow.camera.top = 90; sun.shadow.camera.bottom = -90;
scene.add(sun);
const mat = (color, roughness=.8, metalness=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness });
const grassMat=mat(0x8eae88), sidewalkMat=mat(0xc5c4b8), roadMat=mat(0x3c4548), lineMat=mat(0xe3e2d4), limeMat=mat(0xdaf26d), blueMat=mat(0x59d9ec,.4,.15);
const boxGeo=new THREE.BoxGeometry(1,1,1), cylGeo=new THREE.CylinderGeometry(.5,.5,1,12), sphereGeo=new THREE.SphereGeometry(1,12,8);
function box(parent,material,x,y,z,sx,sy,sz){const m=new THREE.Mesh(boxGeo,material);m.position.set(x,y,z);m.scale.set(sx,sy,sz);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function cylinder(parent,material,x,y,z,r,h,segments=12){const m=new THREE.Mesh(new THREE.CylinderGeometry(r,r,h,segments),material);m.position.set(x,y,z);m.castShadow=true;parent.add(m);return m}

// A calm, sunlit downtown built from lightweight procedural geometry.
box(scene,grassMat,0,-.24,285,240,.3,820);
box(scene,roadMat,0,-.04,285,15,.22,820);
box(scene,mat(0x555d5b),0,-.16,285,16,.12,820);
for(const side of [-1,1]){
  box(scene,sidewalkMat,side*8.4,.02,285,1.8,.24,820);
  box(scene,mat(0x9bba91),side*13,.05,285,7,.2,820);
  // Repeated building blocks with warm facades and varied roof lines.
  for(let i=0;i<24;i++){
    const z=-60+i*30+(i%2)*5, h=10+(i*17%19), w=7+(i*11%8), x=side*(17+w/2);
    const colors=[0xd9c8ac,0xe1dbca,0xbecbc0,0xd7b89c,0xa9c0bd,0xe0d2bd];
    const facade=mat(colors[(i+(side>0?2:0))%colors.length]);
    box(scene,facade,x,h/2,z,w,h,18+(i%3)*3);
    box(scene,mat(0xa6a89b),x,h+.12,z,w+.4,.3,19+(i%3)*3);
    // Window strips, alternating sunlit panes and dark recesses.
    const win=mat(i%2?0x78999b:0x66878d,.35,.08);
    for(let floor=1;floor<h/3;floor++) for(let col=0;col<3;col++){
      box(scene,win,x-side*w*.28+col*w*.28,floor*2.7,z-9.15,w*.13,1.25,.06);
      box(scene,win,x-side*w*.28+col*w*.28,floor*2.7,z+9.15,w*.13,1.25,.06);
    }
    if(i%3===0){box(scene,mat(0x9b927e),x,h+1.1,z,w*.55,1.8,5);}
  }
  // Trees and street lamps on the curb.
  for(let i=0;i<33;i++){
    const z=-35+i*20;
    cylinder(scene,mat(0x745a40),side*9.7,1.2,z,.2,2.4,7);
    const crown=new THREE.Mesh(sphereGeo,mat(i%2?0x527b5f:0x638866));crown.position.set(side*9.7,3.15,z);crown.scale.set(1.05,1.35,1.05);crown.castShadow=true;scene.add(crown);
    if(i%2===0){cylinder(scene,mat(0x596a69),side*11.2,3,z,.075,6,8);box(scene,mat(0xe8dfb9),side*11.2,5.9,z+.35,.65,.16,.9);}
  }
}
// Asphalt lane markings, cross streets, and route guide lights.
for(let z=-90;z<700;z+=10){box(scene,lineMat,0,.085,z,.16,.025,4.2)}
for(const x of [-7.2,7.2])box(scene,mat(0x8e9290),x,.09,285,.12,.02,820);
for(const z of [178,338,498]){
  box(scene,mat(0x4d5657),0,.005,z,130,.18,12);
  for(let x=-56;x<60;x+=8)box(scene,lineMat,x,.11,z,.13,.025,4);
  for(let i=0;i<6;i++)box(scene,mat(0xf1edcf),-5.8+i*2.25,.1,z-8,1.5,.04,5);
}

const bus=new THREE.Group();scene.add(bus);
const busPaint=mat(0xf1d34d,.34,.12), busDark=mat(0x192a32,.4,.15), glassMat=new THREE.MeshStandardMaterial({color:0x244654,roughness:.2,metalness:.18,transparent:true,opacity:.9}), tireMat=mat(0x20292b), hubMat=mat(0xb9c4c0,.3,.55), headlightMat=new THREE.MeshBasicMaterial({color:0xfff0bc}), tailMat=new THREE.MeshBasicMaterial({color:0xff4b37});
box(bus,busDark,0,.72,0,2.48,.65,6.6);
box(bus,busPaint,0,1.7,0,2.55,1.65,6.15);
box(bus,busPaint,0,2.75,.65,2.5,.75,4.75);
box(bus,busDark,0,2.35,3.25,2.5,1.8,.12);
// Panoramic windshield and side windows.
box(bus,glassMat,0,2.7,3.33,2.2,1.05,.035);
for(const side of [-1,1]){
  box(bus,glassMat,side*1.285,2.75,.25,.035,.92,1.55);
  box(bus,glassMat,side*1.285,2.75,-1.55,.035,.92,1.65);
  box(bus,mat(0x1d3037),side*1.3,1.55,-.85,.055,.15,.06);
  box(bus,mat(0xe7c344),side*1.29,1.05,.45,.035,.13,2.55);
  for(const z of [-2.25,2.15]){
    const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.55,.55,.3,16),tireMat);wheel.rotation.z=Math.PI/2;wheel.position.set(side*1.3,.62,z);wheel.castShadow=true;bus.add(wheel);
    const hub=new THREE.Mesh(new THREE.CylinderGeometry(.25,.25,.32,12),hubMat);hub.rotation.z=Math.PI/2;hub.position.set(side*1.3,.62,z);bus.add(hub);
  }
}
box(bus,mat(0xe9c642),0,.95,3.29,2.2,.22,.11);
for(const x of [-.9,.9]){box(bus,headlightMat,x,1.32,3.32,.32,.28,.05);box(bus,tailMat,x,1.45,-3.3,.25,.42,.05)}
box(bus,mat(0xf7e177),0,1.18,3.32,.72,.16,.06);
// A small route sign above the windshield.
box(bus,mat(0x183345),0,3.11,3.25,.95,.28,.08);
box(bus,mat(0xb9f1d0),0,3.12,3.3,.67,.045,.02);

const stops=[{z:110,name:'OLD TOWN',count:6},{z:270,name:'MARKET SQUARE',count:5},{z:430,name:'RIVERFRONT',count:7}];
const stopMeshes=[];
for(const [idx,s] of stops.entries()){
  // Curbside stop platform, shelter, pole, and a luminous boarding target.
  box(scene,mat(0xaaa99c),-9.65,.18,s.z,3.4,.35,17);
  box(scene,mat(0x566768,.3,.2),-10.4,1.55,s.z-1.6,.12,3.2,4.5);
  box(scene,mat(0x9eb7b2,.25,.2),-10.4,2.45,s.z-1.6,.12,.12,4.5);
  box(scene,mat(0x172b38),-9.1,1.75,s.z-7.5,.32,2.1,.35);
  box(scene,mat(0xdaf26d),-9.1,2.75,s.z-7.5,.65,.45,.25);
  // glowing waypoint ring sits in the travel lane, fading with distance.
  const ring=new THREE.Mesh(new THREE.TorusGeometry(2.1,.13,8,36),new THREE.MeshBasicMaterial({color:0x6ee5ec}));ring.rotation.x=Math.PI/2;ring.position.set(0,.22,s.z);scene.add(ring);stopMeshes.push(ring);
  // Bench
  box(scene,mat(0x80684d),-9.3,.75,s.z+2.7,1.5,.12, .55);
  box(scene,mat(0x5d665f),-9.3,.45,s.z+2.7,.12,.6,.48);
  s.index=idx;
}

// A few local cars add scale and traffic awareness without blocking the route.
const traffic=[];
function makeCar(x,z,color,speed){const g=new THREE.Group();scene.add(g);box(g,mat(color,.42,.1),0,.7,0,1.7,.9,3.5);box(g,glassMat,0,1.35,-.1,1.35,.55,1.65);for(const side of [-1,1])for(const zz of [-1,1]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.29,.29,.16,10),tireMat);w.rotation.z=Math.PI/2;w.position.set(side*.88,.36,zz*1.1);g.add(w)}g.position.set(x,0,z);traffic.push({g,x,z,speed});}
makeCar(4.5,85,0xd47751,15);makeCar(-4.4,205,0x557c9c,19);makeCar(4.5,310,0x7d8f6e,17);makeCar(-4.5,370,0xc0ad72,14);

// HUD mini-map is a stylized route plan, rendered separately for crisp UI.
const mapCanvas=document.querySelector('#map'), mapCtx=mapCanvas.getContext('2d');
function drawMap(){const c=mapCtx,w=168,h=145;c.clearRect(0,0,w,h);c.fillStyle='#182a36';c.fillRect(0,0,w,h);c.strokeStyle='#344a51';c.lineWidth=7;for(let x=14;x<w;x+=34){c.beginPath();c.moveTo(x,0);c.lineTo(x,h);c.stroke()}for(let y=10;y<h;y+=34){c.beginPath();c.moveTo(0,y);c.lineTo(w,y);c.stroke()}c.strokeStyle='#d9f36a';c.lineWidth=2;c.setLineDash([4,3]);c.beginPath();c.moveTo(84,127);c.lineTo(84,15);c.stroke();c.setLineDash([]);stops.forEach((s,i)=>{const y=127-i*48;c.beginPath();c.arc(84,y,3.3,0,Math.PI*2);c.fillStyle=i<stopIdx?'#829087':i===stopIdx?'#6ee5ec':'#d9f36a';c.fill()});const y=127-(bus.position.z/160)*48;c.save();c.translate(84,Math.max(8,Math.min(136,y)));c.rotate(0);c.fillStyle='#fff';c.beginPath();c.moveTo(0,-5);c.lineTo(4,4);c.lineTo(-4,4);c.closePath();c.fill();c.restore()}

let running=false, stopIdx=0, speed=0, steering=0, doorOpen=false, parkingBrake=false, passengers=0, boarded=false, completed=false, elapsed=0, safety=100, toastTimer=0, boardingTimer=0;
const keys=new Set(), touch=new Set();
const $=s=>document.querySelector(s);
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2500)}
